(() => {
  const gameView = document.getElementById('gameView');
  const boardBackdrop = document.getElementById('boardBackdrop');
  if (!gameView || !boardBackdrop) return;

  let syncQueued = false;

  function applyGeneratedFrame() {
    // The gameplay frame is now generated by CSS. Retire all raster backdrop
    // delivery so the canvas can fill any viewport without inheriting a fixed
    // portrait image ratio or forcing the Teddy to stretch.
    if (boardBackdrop.style.backgroundImage !== 'none') {
      boardBackdrop.style.backgroundImage = 'none';
    }
    if (boardBackdrop.style.opacity !== '0') {
      boardBackdrop.style.opacity = '0';
    }

    gameView.style.removeProperty('background-image');
    gameView.style.removeProperty('background-position');
    gameView.style.removeProperty('background-size');
    gameView.style.removeProperty('background-repeat');

    gameView.classList.add('has-gameplay-backdrop', 'has-generated-gameplay-frame');
    gameView.dataset.gameplayBackdropStatus = 'loaded';
    gameView.dataset.gameplayBackdropMode = 'generated-css';
    delete gameView.dataset.gameplayBackdropUrl;
    delete gameView.dataset.gameplayBackdropCrop;
  }

  function queueSync() {
    if (syncQueued) return;
    syncQueued = true;
    queueMicrotask(() => {
      syncQueued = false;
      applyGeneratedFrame();
    });
  }

  new MutationObserver(queueSync).observe(boardBackdrop, {
    attributes: true,
    attributeFilter: ['style', 'data-gameplay-backdrop-src'],
  });

  queueSync();
})();
